}

pub fn zero(comptime T: type, count: usize, value: T) []T {
    const out = alloc(T, count);
    @memset(out, value);
    return out;
}
pub fn indexOf(items: anytype, name: []const u8) usize {
    for (items, 0..) |item, i| if (eq(item.name, name)) return i;
    unreachable;
}

pub const Record = struct { number: usize, line: []const u8 };
pub fn dataLines(io: std.Io, path: []const u8) ![]const Record {
    var out: std.ArrayList(Record) = .empty;
    for (try readLines(io, path), 1..) |line, index| if (line.len > 0 and line[0] != '#') append(Record,
         &out, .{ .number = index, .line = line });
    return out.items;
}
pub const Element = struct { symbol: []const u8, number: i64, weight: i64, valences: []const i64 };
pub fn readElements(io: std.Io) ![]const Element {
    var elements: std.ArrayList(Element) = .empty;
    for (try dataLines(io, "input/elements.txt")) |record| {
        const f = words(record.line);
        const values = split(f[3], ',');
        const valences = alloc(i64, values.len);
        for (values, valences) |value, *v| v.* = number(value);
        append(Element, &elements, .{ .symbol = f[0], .number = number(f[1]), .weight = number(f[2]),
             .valences = valences });
    }
    return elements.items;
}
pub fn findElement(elements: []const Element, symbol: []const u8) ?usize {
    for (elements, 0..) |element, index| if (eq(element.symbol, symbol)) return index;
    return null;
}
pub const organic = [_][]const u8{ "B", "C", "N", "O", "P", "S", "F", "Cl", "Br", "I" };
pub fn isOrganic(symbol: []const u8) bool {
    for (organic) |value| if (eq(symbol, value)) return true;
    return false;
}
pub fn aromaticElement(symbol: []const u8) bool {
    return symbol.len == 1 and std.mem.indexOfScalar(u8, "BCNOPS", symbol[0]) != null;
}
pub const AnalysisError = struct { reason: []const u8, column: usize };
pub const Choice = struct { element: usize, aromatic: bool };
pub const Atom = struct { element: usize = 0, aromatic: bool = false, mass: i64 = 0, charge: i64 = 0,
     hydrogens: i64 = 0, bracket: bool = false, column: usize = 0, choices: ?[]const Choice = null,
     aromatic_match: ?bool = null };
pub const Bond = struct { first: usize, second: usize, symbol: u8 = 0, kind: u8 = 0, multiplicity: i64 = 0,
     ring: bool = false };
pub const Neighbor = struct { atom: usize, bond: usize };
pub const Ring = []const usize;
pub fn atomBit(index: usize) u512 {
    return @as(u512, 1) << @intCast(index);
}
pub const Molecule = struct {
    elements: []const Element,
    atoms: std.ArrayList(Atom) = .empty,
    bonds: std.ArrayList(Bond) = .empty,
    neighbors: std.ArrayList(std.ArrayList(Neighbor)) = .empty,
    ordered: []const usize = &.{},
    rings: []const Ring = &.{},
    ring_atoms: u512 = 0,
    name: []const u8 = "",
    pub fn addAtom(self: *Molecule, atom: Atom) usize {
        const index = self.atoms.items.len;
        append(Atom, &self.atoms, atom);
        append(std.ArrayList(Neighbor), &self.neighbors, .empty);
        return index;
    }
    pub fn addBond(self: *Molecule, first: usize, second: usize, symbol: u8) usize {
        const index = self.bonds.items.len;
        append(Bond, &self.bonds, .{ .first = @min(first, second), .second = @max(first, second), .symbol = symbol });
        append(Neighbor, &self.neighbors.items[first], .{ .atom = second, .bond = index });
        append(Neighbor, &self.neighbors.items[second], .{ .atom = first, .bond = index });
        return index;
    }
    pub fn bondBetween(self: *const Molecule, first: usize, second: usize) ?usize {
        for (self.neighbors.items[first].items) |neighbor| if (neighbor.atom == second) return neighbor.bond;
        return null;
    }
    pub fn degree(self: *const Molecule, index: usize) usize {
        return self.neighbors.items[index].items.len;
    }
    pub fn baseTotal(self: *const Molecule, index: usize) i64 {
        var result: i64 = 0;
        const base = [5]i64{ 0, 1, 2, 3, 1 };
        for (self.neighbors.items[index].items) |neighbor| result += base[self.bonds.items[neighbor.bond].kind];
        return result;
    }
    pub fn bondTotal(self: *const Molecule, index: usize) i64 {
        var result: i64 = 0;
        for (self.neighbors.items[index].items) |neighbor| result += self.bonds.items[neighbor.bond].multiplicity;
        return result;
    }
    pub fn finalize(self: *Molecule) void {
        for (self.neighbors.items) |*list| std.mem.sort(Neighbor, list.items, {}, struct {
            fn less(_: void, a: Neighbor, b: Neighbor) bool {
                return a.atom < b.atom;
            }
        }.less);
        const ordered = alloc(usize, self.bonds.items.len);
        for (ordered, 0..) |*index, j| index.* = j;
        std.mem.sort(usize, ordered, self.bonds.items, struct {
            fn less(bonds: []Bond, a: usize, b: usize) bool {
                return if (bonds[a].first == bonds[b].first) bonds[a].second < bonds[b].second else bonds[a].first < bonds[b].first;
            }
        }.less);
        self.ordered = ordered;
    }
};
pub const ParsedAtom = struct { atom: Atom = .{}, end: usize = 0, failure: ?AnalysisError = null };
pub fn needsPi(molecule: *const Molecule, index: usize, hydrogens: ?i64) bool {
    const atom = molecule.atoms.items[index];
    const occupied = molecule.baseTotal(index) + (hydrogens orelse atom.hydrogens);
    return atom.aromatic and molecule.elements[atom.element].valences[0] + atom.charge >= occupied + 1;
}
pub fn organicHydrogens(element: Element, total: i64) ?i64 {
    for (element.valences) |valence| if (valence >= total) return valence - total;
    return null;
}

const std = @import("std");
const m = @import("molecule.zig");
const Candidate = struct { sequence: []const usize, bonds: u512, order: usize };
fn canonicalRing(sequence: []const usize) []const usize {
    var first: usize = 0;
    for (sequence, 0..) |atom, index| if (atom < sequence[first]) {
        first = index;
    };
    const out = m.alloc(usize, sequence.len);
    const forward = sequence[(first + 1) % sequence.len] < sequence[(first + sequence.len - 1) % sequence.len];
    for (out, 0..) |*atom, index| atom.* = sequence[(first + (if (forward) index else sequence.len - index)) % sequence.len];
    return out;
}
fn ringLess(_: void, a: m.Ring, b: m.Ring) bool {
    if (a.len != b.len) return a.len < b.len;
    for (a, b) |first, second| if (first != second) return first < second;
    return false;
}
pub fn findRings(molecule: *m.Molecule) void {
    const count = molecule.atoms.items.len;
    var candidates: std.ArrayList(Candidate) = .empty;
    var seen: std.AutoHashMapUnmanaged(u512, void) = .empty;
    for (0..count) |root| {
        const parents = m.zero(?usize, count, null);
        const visited = m.zero(bool, count, false);
        const queue = m.alloc(usize, count);
        visited[root] = true;
        queue[0] = root;
        var read: usize = 0;
        var size: usize = 1;
        while (read < size) : (read += 1) {
            const atom = queue[read];
            for (molecule.neighbors.items[atom].items) |neighbor| if (!visited[neighbor.atom]) {
                visited[neighbor.atom] = true;
                parents[neighbor.atom] = atom;
                queue[size] = neighbor.atom;
                size += 1;
            };
        }
        const paths = m.alloc([]const usize, count);
        const masks = m.alloc(u512, count);
        for (0..count) |atom| {
            var path: std.ArrayList(usize) = .empty;
            var current: ?usize = atom;
            var mask: u512 = 0;
            while (current) |index| {
                m.append(usize, &path, index);
                mask |= m.atomBit(index);
                current = parents[index];
            }
            paths[atom] = path.items;
            masks[atom] = mask;
        }
        for (molecule.ordered) |index| {
            const bond = molecule.bonds.items[index];
            const first = bond.first;
            const second = bond.second;
            if (parents[first] == second or parents[second] == first or masks[first] & masks[second] != m.atomBit(root)) continue;
            const sequence = m.alloc(usize, paths[first].len + paths[second].len - 1);
            for (paths[first], 0..) |atom, j| sequence[paths[first].len - 1 - j] = atom;
            @memcpy(sequence[paths[first].len..], paths[second][0 .. paths[second].len - 1]);
            var bonds: u512 = 0;
            for (sequence, 0..) |atom, j| bonds |= m.atomBit(molecule.bondBetween(atom, sequence[(j + 1) % sequence.len]).?);
            if (seen.contains(bonds)) continue;
            seen.put(m.allocator, bonds, {}) catch @panic("allocation failed");
            m.append(Candidate, &candidates, .{ .sequence = sequence, .bonds = bonds, .order = candidates.items.len });
        }
    }
    std.mem.sort(Candidate, candidates.items, {}, struct {
        fn less(_: void, a: Candidate, b: Candidate) bool {
            return if (a.sequence.len == b.sequence.len) a.order < b.order else a.sequence.len < b.sequence.len;
        }
    }.less);
    var basis: [512]?u512 = @splat(null);
    var rings: std.ArrayList(m.Ring) = .empty;
    for (candidates.items) |candidate| {
        var reduced = candidate.bonds;
        while (reduced != 0) {
            const pivot: usize = 511 - @as(usize, @clz(reduced));
            if (basis[pivot]) |value| reduced ^= value else {
                basis[pivot] = reduced;
                m.append(m.Ring, &rings, canonicalRing(candidate.sequence));
                break;
            }
        }
    }
    std.mem.sort(m.Ring, rings.items, {}, ringLess);
    molecule.rings = rings.items;
    for (molecule.rings) |ring| for (ring, 0..) |atom, index| {
        molecule.ring_atoms |= m.atomBit(atom);
        molecule.bonds.items[molecule.bondBetween(atom, ring[(index + 1) % ring.len]).?].ring = true;
    };
}
fn matchSystem(molecule: *const m.Molecule, unpaired: u512, selected: *u512) bool {
    if (unpaired == 0) return true;
    const first: usize = @ctz(unpaired);
    const rest = unpaired & ~m.atomBit(first);
    for (molecule.neighbors.items[first].items) |neighbor| {
        if (rest & m.atomBit(neighbor.atom) == 0 or molecule.bonds.items[neighbor.bond].kind != 4) continue;
        const bit = m.atomBit(neighbor.bond);
        selected.* |= bit;
        if (matchSystem(molecule, rest & ~m.atomBit(neighbor.atom), selected)) return true;
        selected.* &= ~bit;
    }
    return false;
}
pub fn kekulize(molecule: *m.Molecule, needing: u512) ?m.AnalysisError {
    var remaining = needing;
    var selected: u512 = 0;
    while (remaining != 0) {
        const first: usize = @ctz(remaining);
        var system = m.atomBit(first);
        remaining &= ~system;
        var frontier = system;
        while (frontier != 0) {
            const atom: usize = @ctz(frontier);
            frontier &= ~m.atomBit(atom);
            for (molecule.neighbors.items[atom].items) |neighbor| {
                const bit = m.atomBit(neighbor.atom);
                if (remaining & bit != 0 and molecule.bonds.items[neighbor.bond].kind == 4) {
                    remaining &= ~bit;
                    system |= bit;
                    frontier |= bit;
                }
            }
        }
        if (!matchSystem(molecule, system, &selected)) return .{ .reason = "kekulization failed",
             .column = molecule.atoms.items[first].column };
    }
    for (molecule.bonds.items, 0..) |*bond, index| bond.multiplicity = if (bond.kind == 4) (if (selected & m.atomBit(index) != 0) @as(i64,
         2) else 1) else bond.kind;
    return null;
}

const std = @import("std");
const m = @import("molecule.zig");
const parser = @import("smiles_parser.zig");
pub fn readPatternAtom(text: []const u8, position: usize, elements: []const m.Element) m.ParsedAtom {
    const character = text[position];
    if (character == '*' or character == 'A' or character == 'a') return .{ .atom = .{ .aromatic_match = if (character == '*') null else character == 'a' },
         .end = position + 1 };
    if (character == '[') {
        const offset = std.mem.indexOfScalar(u8, text[position + 1 ..], ']') orelse return .{ .failure = .{ .reason = "unclosed bracket",
             .column = position + 1 } };
        const end = position + 1 + offset;
        var choices: std.ArrayList(m.Choice) = .empty;
        for (m.split(text[position + 1 .. end], ',')) |item| {
            const organic = parser.readOrganic(item, 0, elements) orelse return .{ .failure = .{ .reason = "bad bracket atom",
                 .column = position + 1 } };
            if (organic.end != item.len) return .{ .failure = .{ .reason = "bad bracket atom",
                 .column = position + 1 } };
            m.append(m.Choice, &choices, .{ .element = organic.element, .aromatic = organic.aromatic });
        }
        return .{ .atom = .{ .choices = choices.items }, .end = end + 1 };
    }
    const organic = parser.readOrganic(text, position, elements) orelse return .{ .failure = .{ .reason = "unexpected character",
         .column = position + 1 } };
    const choices = m.alloc(m.Choice, 1);
    choices[0] = .{ .element = organic.element, .aromatic = organic.aromatic };
    return .{ .atom = .{ .choices = choices }, .end = organic.end };
}
pub fn moleculePattern(molecule: *const m.Molecule) *m.Molecule {
    const pattern = m.create(m.Molecule, .{ .elements = molecule.elements });
    for (molecule.atoms.items) |atom| {
        const choices = m.alloc(m.Choice, 1);
        choices[0] = .{ .element = atom.element, .aromatic = atom.aromatic };
        _ = pattern.addAtom(.{ .choices = choices });
    }
    for (molecule.ordered) |index| {
        const bond = molecule.bonds.items[index];
        _ = pattern.addBond(bond.first, bond.second, bond.kind);
    }
    pattern.finalize();
    return pattern;
}
fn atomMatches(pattern: m.Atom, atom: m.Atom) bool {
    if (pattern.choices) |choices| {
        for (choices) |choice| if (choice.element == atom.element and choice.aromatic == atom.aromatic) return true;
        return false;
    }
    return pattern.aromatic_match == null or pattern.aromatic_match.? == atom.aromatic;
}
pub fn bondMatches(pattern: m.Bond, target: m.Bond) bool {
    return if (pattern.symbol == 0) target.kind == 1 or target.kind == 4 else if (pattern.symbol == 5) true else pattern.symbol == target.kind;
}
pub const Embeddings = struct { count: i64 = 0, unique: usize = 0, mapping: []const usize = &.{} };
const Matcher = struct {
    pattern: *const m.Molecule,
    molecule: *const m.Molecule,
    candidates: []const bool,
    mapping: []usize,
    unique: std.AutoHashMapUnmanaged(u128, void) = .empty,
    result: Embeddings = .{},
    allocator: std.mem.Allocator,
    fn assign(self: *Matcher, index: usize, used: u128) void {
        if (index == self.pattern.atoms.items.len) {
            self.result.count += 1;
            self.unique.put(self.allocator, used, {}) catch @panic("allocation failed");
            if (self.result.mapping.len == 0) self.result.mapping = m.dupe(usize, self.mapping);
            return;
        }
        const count = self.molecule.atoms.items.len;
        for (0..count) |atom| {
            const bit = @as(u128, 1) << @intCast(atom);
            if (used & bit != 0 or !self.candidates[index * count + atom]) continue;
            var valid = true;
            for (self.pattern.neighbors.items[index].items) |neighbor| {
                if (neighbor.atom >= index) continue;
                const target = self.molecule.bondBetween(atom, self.mapping[neighbor.atom]) orelse {
                    valid = false;
                    break;
                };
                if (!bondMatches(self.pattern.bonds.items[neighbor.bond], self.molecule.bonds.items[target])) {
                    valid = false;
                    break;
                }
            }
            if (valid) {
                self.mapping[index] = atom;
                self.assign(index + 1, used | bit);
            }
        }
    }
};
pub fn embeddings(pattern: *const m.Molecule, molecule: *const m.Molecule, work_allocator: std.mem.Allocator) Embeddings {
    if (pattern.atoms.items.len > molecule.atoms.items.len) return .{};
    var arena: std.heap.ArenaAllocator = .init(work_allocator);
    defer arena.deinit();
    const allocator = arena.allocator();
    const count = molecule.atoms.items.len;
    const candidates = allocator.alloc(bool, pattern.atoms.items.len * count) catch @panic("allocation failed");
    for (pattern.atoms.items, 0..) |pattern_atom, index| for (molecule.atoms.items, 0..) |atom, id| {
        candidates[index * count + id] = atomMatches(pattern_atom, atom) and molecule.degree(id) >= pattern.degree(index);
    };
    var matcher: Matcher = .{ .pattern = pattern, .molecule = molecule, .candidates = candidates,
         .mapping = allocator.alloc(usize, pattern.atoms.items.len) catch @panic("allocation failed"),
         .allocator = allocator };
    matcher.assign(0, 0);
    matcher.result.unique = matcher.unique.count();
    return matcher.result;
}
pub const Fingerprint = struct {
    bits: [16]u64 = @splat(0),
    paths: i64 = 0,
    pub fn count(self: Fingerprint) usize {
        var total: usize = 0;
        for (self.bits) |word| total += @popCount(word);
        return total;
    }
};
const Fingerprinter = struct {
    molecule: *const m.Molecule,
    codes: []const i64,
    result: Fingerprint = .{},
    fn extend(self: *Fingerprinter, atom: usize, depth: usize, value: i64, used: u128) void {
        self.result.paths += 1;
        const bit = m.u(@mod(value, 1024));
        self.result.bits[bit / 64] |= @as(u64, 1) << @intCast(bit % 64);
        if (depth == 5) return;
        for (self.molecule.neighbors.items[atom].items) |neighbor| {
            const mask = @as(u128, 1) << @intCast(neighbor.atom);
            if (used & mask != 0) continue;
            var next = @mod(value * 31 + self.molecule.bonds.items[neighbor.bond].kind, 1000003);
            next = @mod(next * 31 + self.codes[neighbor.atom], 1000003);
            self.extend(neighbor.atom, depth + 1, next, used | mask);
        }
    }
};
pub fn fingerprint(molecule: *const m.Molecule) Fingerprint {
    const codes = m.alloc(i64, molecule.atoms.items.len);
    for (molecule.atoms.items, codes, 0..) |atom, *code, index| code.* = 16 * molecule.elements[atom.element].number + 8 * @as(i64,
         @intFromBool(atom.aromatic)) + m.n(molecule.degree(index));
    var printer: Fingerprinter = .{ .molecule = molecule, .codes = codes };
    for (codes, 0..) |code, index| printer.extend(index, 0, code, @as(u128, 1) << @intCast(index));
    return printer.result;
}
pub const Similarity = struct {
    common: i64,
    union_count: i64,
    pub fn less(self: Similarity, other: Similarity) bool {
        return self.common * other.union_count < other.common * self.union_count;
    }
    pub fn text(self: Similarity) []const u8 {
        var a = self.common;
        var b = self.union_count;
        while (b != 0) {
            const next = @mod(a, b);
            a = b;
            b = next;
        }
        return m.fmt("{d}/{d}", .{ @divTrunc(self.common, a), @divTrunc(self.union_count, a) });
    }
};
pub fn tanimoto(first: Fingerprint, second: Fingerprint) Similarity {
    var common: i64 = 0;
    var union_count: i64 = 0;
    for (first.bits, second.bits) |a, b| {
        common += @popCount(a & b);
        union_count += @popCount(a | b);
    }
    return .{ .common = common, .union_count = union_count };
}

const std = @import("std");
const m = @import("molecule.zig");
pub const Organic = struct { element: usize, aromatic: bool, end: usize };
pub fn readOrganic(text: []const u8, position: usize, elements: []const m.Element) ?Organic {
    if (position >= text.len) return null;
    if (position + 1 < text.len and (m.eq(text[position .. position + 2], "Cl") or m.eq(text[position .. position + 2],
         "Br"))) return .{ .element = m.findElement(elements, text[position .. position + 2]).?,
         .aromatic = false, .end = position + 2 };
    const character = text[position];
    if (std.mem.indexOfScalar(u8, "BCNOPSFI", character) != null) return .{ .element = m.findElement(elements,
         text[position .. position + 1]).?, .aromatic = false, .end = position + 1 };
    if (std.mem.indexOfScalar(u8, "bcnops", character) != null) {
        const symbol = [1]u8{std.ascii.toUpper(character)};
        return .{ .element = m.findElement(elements, &symbol).?, .aromatic = true, .end = position + 1 };
    }
    return null;
}
fn digit(character: u8) bool {
    return character >= '0' and character <= '9';
}
fn failure(reason: []const u8, column: usize) m.ParsedAtom {
    return .{ .failure = .{ .reason = reason, .column = column } };
}
pub fn readAtom(text: []const u8, start: usize, elements: []const m.Element) m.ParsedAtom {
    if (text[start] != '[') {
        const organic = readOrganic(text, start, elements) orelse return failure("unexpected character", start + 1);
        return .{ .atom = .{ .element = organic.element, .aromatic = organic.aromatic, .column = start + 1 },
             .end = organic.end };
    }
    const offset = std.mem.indexOfScalar(u8, text[start + 1 ..], ']') orelse return failure("unclosed bracket",
         start + 1);
    const end = start + 1 + offset;
    const content = text[start + 1 .. end];
    var position: usize = 0;
    while (position < content.len and digit(content[position])) : (position += 1) {}
    if (position >= 4 or (position > 0 and content[0] == '0') or position == content.len) return failure("bad bracket atom",
         start + 1);
    var atom: m.Atom = .{ .mass = if (position > 0) m.number(content[0..position]) else 0,
         .bracket = true, .column = start + 1 };
    const character = content[position];
    if (std.mem.indexOfScalar(u8, "bcnops", character) != null) {
        const symbol = [1]u8{std.ascii.toUpper(character)};
        atom.element = m.findElement(elements, &symbol).?;
        atom.aromatic = true;
        position += 1;
    } else if (character >= 'A' and character <= 'Z') {
        const pair = if (position + 1 < content.len and content[position + 1] >= 'a' and content[position + 1] <= 'z') m.findElement(elements,
             content[position .. position + 2]) else null;
        if (pair) |element| {
            atom.element = element;
            position += 2;
        } else if (m.findElement(elements, content[position .. position + 1])) |element| {
            atom.element = element;
            position += 1;
        } else return failure("unknown element", start + 1);
    } else return failure("bad bracket atom", start + 1);
    if (position + 1 < content.len and m.eq(content[position .. position + 2], "@@")) position += 2 else if (position < content.len and content[position] == '@') position += 1;
    if (position < content.len and content[position] == 'H') {
        atom.hydrogens = 1;
        position += 1;
        if (position < content.len and digit(content[position])) {
            atom.hydrogens = content[position] - '0';
            position += 1;
        }
    }
    if (position < content.len and (content[position] == '+' or content[position] == '-')) {
        atom.charge = if (content[position] == '+') 1 else -1;
        position += 1;
        if (position < content.len and content[position] >= '1' and content[position] <= '9') {
            atom.charge *= content[position] - '0';
            position += 1;
        }
    }
    if (position != content.len) return failure("bad bracket atom", start + 1);
    return .{ .atom = atom, .end = end + 1 };
}
fn symbolKind(character: u8, pattern: bool) ?u8 {
    return switch (character) {
        '-' => 1,
        '=' => 2,
        '#' => 3,
        ':' => 4,
        '~' => if (pattern) 5 else null,
        '/', '\\' => if (pattern) null else 1,
        else => null,
    };
}
const Pending = struct { kind: u8, column: usize };
const Branch = struct { atom: usize, column: usize };
const OpenRing = struct { atom: usize, kind: u8, column: usize };
pub const Result = struct { molecule: ?*m.Molecule = null, failure: ?m.AnalysisError = null };
fn reject(reason: []const u8, column: usize) Result {
    return .{ .failure = .{ .reason = reason, .column = column } };
}
pub fn parse(text: []const u8, elements: []const m.Element, comptime pattern: bool, comptime atom_reader: anytype) Result {
    const molecule = m.create(m.Molecule, .{ .elements = elements });
    var current: ?usize = null;
    var pending: ?Pending = null;
    var branches: std.ArrayList(Branch) = .empty;
    var open: [100]?OpenRing = @splat(null);
    var position: usize = 0;
    while (position < text.len) {
        const character = text[position];
        const column = position + 1;
        if (symbolKind(character, pattern)) |kind| {
            if (current == null or pending != null) return reject("misplaced bond", column);
            pending = .{ .kind = kind, .column = column };
            position += 1;
        } else if (character == '(') {
            if (current == null or pending != null or (position > 0 and text[position - 1] == '(')) return reject("misplaced branch",
                 column);
            m.append(Branch, &branches, .{ .atom = current.?, .column = column });
            position += 1;
        } else if (character == ')') {
            if (branches.items.len == 0) return reject("unmatched parenthesis", column);
            if (pending) |bond| return reject("dangling bond", bond.column);
            if (position > 0 and text[position - 1] == '(') return reject("empty branch", column);
            current = branches.pop().?.atom;
            position += 1;
        } else if (digit(character) or character == '%') {
            if (current == null) return reject("misplaced ring closure", column);
            var ring: usize = undefined;
            if (character == '%') {
                if (position + 2 >= text.len or !digit(text[position + 1]) or !digit(text[position + 2])) return reject("bad ring number",
                     column);
                ring = @as(usize, text[position + 1] - '0') * 10 + text[position + 2] - '0';
                position += 3;
            } else {
                ring = character - '0';
                position += 1;
            }
            const kind = if (pending) |bond| bond.kind else 0;
            pending = null;
            if (open[ring]) |initial| {
                if (initial.atom == current.?) return reject("self bond", column);
                if (initial.kind != 0 and kind != 0 and initial.kind != kind) return reject("ring bond mismatch",
                     column);
                if (molecule.bondBetween(initial.atom, current.?) != null) return reject("duplicate bond", column);
                _ = molecule.addBond(initial.atom, current.?, if (kind != 0) kind else initial.kind);
                open[ring] = null;
            } else open[ring] = .{ .atom = current.?, .kind = kind, .column = column };
        } else {
            const parsed = atom_reader(text, position, elements);
            if (parsed.failure) |reason| return .{ .failure = reason };
            const atom = molecule.addAtom(parsed.atom);
            if (current) |previous| _ = molecule.addBond(previous, atom, if (pending) |bond| bond.kind else 0);
            current = atom;
            pending = null;
            position = parsed.end;
        }
    }
    if (pending) |bond| return reject("dangling bond", bond.column);
    if (branches.items.len > 0) return reject("unmatched parenthesis", branches.items[0].column);
    var earliest: ?usize = null;
    for (open) |ring| if (ring) |value| {
        if (earliest == null or value.column < earliest.?) earliest = value.column;
    };
    if (earliest) |column| return reject("unclosed ring", column);
    molecule.finalize();
    return .{ .molecule = molecule };
}
